#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
#include <algorithm>
struct DimensionAttributeAudit{static void run(const Graph&g){for(size_t id=0;id<g.elements.size();++id)for(const auto&a:g.elements[id].attributes){auto key=g.strings.at(a.name);std::transform(key.begin(),key.end(),key.begin(),[](unsigned char c){return char(std::tolower(c));});if(key.find("width")==std::string::npos&&key.find("height")==std::string::npos&&key.find("resolution")==std::string::npos&&key.find("aspect")==std::string::npos)continue;std::cout<<"dimension_attribute element="<<id<<" type="<<g.strings.at(g.elements[id].type)<<" name="<<g.strings.at(g.elements[id].name)<<" key="<<g.strings.at(a.name)<<" wire_type="<<unsigned(a.type)<<" count="<<a.values.size();if(a.values.size()==1){if(a.type==2)std::cout<<" int="<<wireInt(a.values[0]);if(a.type==3)std::cout<<" float="<<wireFloat(a.values[0]);if(a.type==5)std::cout<<" text="<<a.values[0].text;}std::cout<<'\n';}}};
int main(){try{auto g=loadGraph("work/roundtrip-11.dmx");auto settings=hierarchyRefs(g,g.elements.at(0),"settings",1);auto render=hierarchyRefs(g,g.elements.at(settings.at(0)),"renderSettings",1);auto id=render.at(0);std::cout<<"render_settings="<<id<<" type="<<g.strings.at(g.elements.at(id).type)<<'\n';for(auto&a:g.elements.at(id).attributes){std::cout<<g.strings.at(a.name)<<" type="<<unsigned(a.type)<<" count="<<a.values.size();if(a.values.size()==1){if(a.type==2)std::cout<<" int="<<wireInt(a.values[0]);if(a.type==3)std::cout<<" float="<<wireFloat(a.values[0]);if(a.type==5)std::cout<<" text="<<a.values[0].text;}std::cout<<'\n';}DimensionAttributeAudit::run(g);return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
